), upserted as (
 insert into public.catalog_recipes (id,name_common,category,category_sub,meal_slot,cuisine,origin,language,difficulty,prep_time,cook_time,servings,serving_size,description,description_simple,description_technical,ingredients,linked_ingredients,instructions,nutrition_per_serving,health_score,taste_profile,dietary_info,allergens,tags,image_url,image_primary_url,is_primary,scannable,updated_at)
 select id,name,'meal',jsonb_build_array(initcap(slot),'Book-curated'),slot,cuisine,origin,'en','medium',prep,cook,4,serving,description,description,
 'Original ROUTINE³ formulation. Macro- and micronutrition are derived from catalog ingredient junctions; cookbook nutrition and health claims are not imported.',ingredients,ingredients,instructions,
 jsonb_build_object('_derivation',jsonb_build_object('method','catalog ingredient junction calculation','source_chain','catalog_recipe_ingredients -> catalog_ingredients -> catalog_ingredient_elements','needs_curation',false)),
 90,'{"taste":{"sweet":3,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":3},"texture":{"creamy":3,"crispy":3,"chewy":3}}'::jsonb,
 '{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true}'::jsonb,allergens,array['book-curated','original-formulation','junction-nutrition','vegan'],
 'https://healthscan.live/images/recipes/world/'||image,'https://healthscan.live/images/recipes/world/'||image,true,true,now()
 from recipes
 on conflict (id) do update set name_common=excluded.name_common,meal_slot=excluded.meal_slot,cuisine=excluded.cuisine,origin=excluded.origin,prep_time=excluded.prep_time,cook_time=excluded.cook_time,servings=excluded.servings,serving_size=excluded.serving_size,description=excluded.description,description_simple=excluded.description_simple,description_technical=excluded.description_technical,ingredients=excluded.ingredients,linked_ingredients=excluded.linked_ingredients,instructions=excluded.instructions,nutrition_per_serving=excluded.nutrition_per_serving,dietary_info=excluded.dietary_info,allergens=excluded.allergens,tags=excluded.tags,image_url=excluded.image_url,image_primary_url=excluded.image_primary_url,updated_at=now()
 returning id
)
insert into public.catalog_recipe_ingredients (recipe_id,ingredient_id,amount_g,unit,sort_order,notes)
select r.id, i->>'id', (i->>'amount_g')::numeric, 'g', ordinality::int, 'Book-curated gram formulation; nutrition derives from linked catalog ingredient'
from recipes r cross join lateral jsonb_array_elements(r.ingredients) with ordinality x(i,ordinality)
join upserted u on u.id=r.id
on conflict (recipe_id,ingredient_id) do update set amount_g=excluded.amount_g,unit=excluded.unit,sort_order=excluded.sort_order,notes=excluded.notes;

-- Canonical calculation surface: macros come from ingredient nutrition JSON;
-- micronutrients remain available through catalog_ingredient_elements.
create or replace view public.catalog_recipe_macro_totals as
select cr.id recipe_id, cr.servings,
 round(sum(cri.amount_g/100.0 * coalesce((ci.nutrition_per_100g->>'energy_kcal')::numeric,0))/nullif(cr.servings,0),1) energy_kcal_per_serving,
 round(sum(cri.amount_g/100.0 * coalesce((ci.nutrition_per_100g->>'protein_g')::numeric,0))/nullif(cr.servings,0),1) protein_g_per_serving,
 round(sum(cri.amount_g/100.0 * coalesce((ci.nutrition_per_100g->>'carbohydrates_g')::numeric,0))/nullif(cr.servings,0),1) carbohydrates_g_per_serving,
 round(sum(cri.amount_g/100.0 * coalesce((ci.nutrition_per_100g->>'fiber_g')::numeric,0))/nullif(cr.servings,0),1) fiber_g_per_serving,
 round(sum(cri.amount_g/100.0 * coalesce((ci.nutrition_per_100g->>'fats_g')::numeric,0))/nullif(cr.servings,0),1) fats_g_per_serving,
 count(*) ingredient_links,
 count(*) filter (where ci.nutrition_per_100g is null) ingredients_missing_macros
from public.catalog_recipes cr
join public.catalog_recipe_ingredients cri on cri.recipe_id=cr.id
join public.catalog_ingredients ci on ci.id=cri.ingredient_id
group by cr.id,cr.servings;

grant select on public.catalog_recipe_macro_totals to anon, authenticated;
notify pgrst, 'reload schema';
